const SAMPLE_PERCENTAGES = [
  78, 64, 35, 82, 55, 42, 71, 88, 27, 63, 74, 39, 30, 68, 58, 46, 81, 33, 24,
];

export const buildMock600ResultResponse = (
  answers: Array<{ questionId: string; answerId: string }> = [],
): unknown => {
  const fromPairs = AXIS_PAIRS.flatMap(([positiveId, negativeId], index) => {
    const percent = SAMPLE_PERCENTAGES[index % SAMPLE_PERCENTAGES.length];

    return [
      { id: positiveId, points: percent, maxPossible: 100 },
      { id: negativeId, points: 100 - percent, maxPossible: 100 },
    ];
  });
  const others = OTHER_ORIENTATIONS.map((id, index) => ({
    id,
    points: 15 + ((index * 17) % 70),
    maxPossible: 100,
  }));

  return {
    surveyId: MOCK_600_SURVEY_ID,
    results: { orientations: [...fromPairs, ...others] },
    answers,
  };
};
